STORY = [('agent', '惠美今天说为了不影响十二歌王和黄金一班的合作，她自己决定退出节目。', "Huimei said today that so she doesn't hurt Twelve Singers and the Golden Class, she has decided to withdraw.", [(387, '今天说她为了'), (389, '和黄金一班的合作'), (390, '她自己决定退出节目')], ''), ('chun_yuqiao', '再想想办法。', 'Give me time to think of another way.', [(394, '再想想办法')], ''), ('bu_xiaogu', '淳于总，吃药了。', "Mr Chun Yuqiao, it's time to take your stomach medicine.", [(395, '淳于总'), (396, '吃药了')], ''), ('chun_yuqiao', '我怎么不记得了？那天我去了。', 'Who says I forgot our pier appointment? That night, I went.', [(401, '不记得了'), (409, '我去了')], ''), ('chun_yuqiao', '在你看来，我们从来都不是一类人？', 'So in your eyes, the two of us have never been the same kind of people?', [(421, '在你看来我们'), (422, '从来都不是一类人')], ''), ('bu_xiaogu', '我怎么会胡思乱想呢，我不会的。', 'How could I ever harbor wild ideas — I never would.', [(427, '我怎么会胡思乱想呢'), (428, '我不会的')], ''), ('bu_xiaogu', '您是领导，是师兄，是我的偶像。我们两个的差距太大了，我应该跟您好好学习。', 'You are my executive, my senior alumnus, and my idol; the gap between us is huge, and I should learn from you.', [(429, '您是领导'), (430, '师兄'), (431, '是我的偶像'), (432, '我们两个的差距太大了'), (433, '我应该跟您好好学习')], ''), ('chun_yuqiao', '我知道了，那现在一切都清楚了。你是一个合格的员工，以后就好好共事吧。', "I understand — everything is crystal clear now. You are a qualified employee; let's simply work together professionally.", [(434, '我知道了'), (435, '那现在一切都清楚了'), (436, '你是一个合格的员工'), (438, '以后就好好共事吧')], ''), ('bu_xiaogu', '别总说没事，您要是心里有什么不舒服或者不开心的，您就跟我说。', "Please don't always say nothing's wrong; if anything is bothering you inside, tell me.", [(442, '别总说没事'), (443, '您要是心里有什么'), (444, '不舒服'), (445, '不开心的'), (446, '您就跟我说')], ''), ('chun_yuqiao', '本来我们就不是一类人，过去不是，现在更不是。', 'We were never the same kind of people in the first place — not in the past, and even less so now.', [(450, '本来我们就不是一类人'), (451, '过去不是 现在更不是')], ''), ('chun_yuqiao', '除了工作，我什么都无所谓。所以现在，契约解除。', 'Outside of work, nothing matters to me at all. So as of right now, our pact is dissolved.', [(454, '除了工作'), (455, '我什么都无所谓'), (456, '所以现在'), (457, '契约解除')], ''), ('bu_xiaogu', '您说什么？', 'What did you just say?', [(458, '您说什么')], '')]
